});

import { generateBoard } from './deck.ts';
import { SelectionKind } from './selection.ts';
import type { Board } from './deck.ts';
import type { Selection } from './selection.ts';

export const ELAPSED_MAX_MS = 359_999_999;
export const MISMATCH_MS = 800;
export const MOVES_MAX = 999_999;

export interface GameState extends Board {
  readonly matched: readonly number[];
  readonly selection: Selection;
  readonly moves: number;
  readonly elapsedMs: number;
  readonly started: boolean;
}

export function createGame(boardCode: string): GameState {
  return {
    ...generateBoard(boardCode),
    matched: [],
    selection: { kind: SelectionKind.closed },
    moves: 0,
    elapsedMs: 0,
    started: false,
  };
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.deck.length;
}

// The board reads one set per game state instead of searching the matched list for every card.
export function faceUpCards(state: Pick<GameState, 'matched' | 'selection'>): ReadonlySet<number> {
  const cards = new Set(state.matched);
  const selection = state.selection;
  if (selection.kind === SelectionKind.one) cards.add(selection.index);
  if (selection.kind === SelectionKind.mismatch) {
    cards.add(selection.first);
    cards.add(selection.second);
  }
  return cards;
}

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isInteger(index) || index < 0 || index >= state.deck.length) return state;
  if (state.matched.includes(index)) return state;
  switch (state.selection.kind) {
    case SelectionKind.closed:
      return { ...state, started: true, selection: { kind: SelectionKind.one, index } };
    case SelectionKind.one: {
      const first = state.selection.index;
      if (first === index) return state;
      const moves = Math.min(MOVES_MAX, state.moves + 1);
      if (state.deck[first] === state.deck[index]) {
        return {
          ...state,
          moves,
          matched: [...state.matched, first, index],
          selection: { kind: SelectionKind.closed },
        };
      }
      return {
        ...state,
        moves,
        selection: { kind: SelectionKind.mismatch, first, second: index, remainingMs: MISMATCH_MS },
      };
    }
    case SelectionKind.mismatch:
      return state;
    default:
      return unreachable(state.selection);
  }
}

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isFinite(milliseconds) || milliseconds <= 0) return state;
  if (!state.started || isWon(state)) return state;
  const elapsedMs = Math.min(ELAPSED_MAX_MS, state.elapsedMs + milliseconds);
  if (state.selection.kind !== SelectionKind.mismatch) return { ...state, elapsedMs };
  const remainingMs = state.selection.remainingMs - milliseconds;
  const selection =
    remainingMs > 0 ? { ...state.selection, remainingMs } : { kind: SelectionKind.closed };
  return { ...state, elapsedMs, selection };
}

function unreachable(value: never): never {
  throw new Error(`Unknown selection: ${String(value)}`);
}

export const StatusLabel = {
  moves: 'Moves:',
  pairs: 'Pairs:',
  time: 'Time:',
  best: 'Best:',
} as const;

import { expect, test } from './browser-test.ts';
import { EXAMPLE_CODE, EXAMPLE_PAIRS } from '../src/game/game.fixture.ts';
import { ReproductionControl } from '../src/game/controls/control-labels.ts';
import { DEFAULT_SIZE, PREFERENCES_KEY, PREFERENCES_VERSION } from '../src/game/session/storage.ts';
import { SelectionKind } from '../src/game/selection.ts';
import { SNAPSHOT_VERSION } from '../src/game/snapshot.ts';
import { StatusLabel } from '../src/game/status/status-labels.ts';
import type { Page } from '@playwright/test';

const PERFECT = EXAMPLE_PAIRS.length;

function shownBest(page: Page) {
  return page
    .locator('.stats > div')
    .filter({ has: page.getByText(StatusLabel.best, { exact: true }) })
    .locator('dd');
}

// Stores a best as an earlier visit would have saved it.
async function saveBest(page: Page, moves: number): Promise<void> {
  const saved = JSON.stringify({
    schemaVersion: PREFERENCES_VERSION,
    size: DEFAULT_SIZE,
    bestMoves: { [DEFAULT_SIZE]: moves },
  });
  await page.evaluate(([key, value]) => localStorage.setItem(key, value), [
    PREFERENCES_KEY,
    saved,
  ] as const);
}

function savedBest(page: Page) {
  return page.evaluate((key) => localStorage.getItem(key), PREFERENCES_KEY);
}

// A worse completed import is the case only a browser can show: the saved best and its label stay as they were.
for (const [saved, imported] of [[PERFECT, PERFECT + 2]] as const)
  test(`a completed import in ${imported} moves leaves a saved best of ${saved} alone`, async ({
    page,
    gameURL,
  }) => {
    await page.goto(gameURL);
    await saveBest(page, saved);
    await page.reload();
    const best = shownBest(page);
    await expect(best).toHaveText(String(saved));
    const before = await savedBest(page);
    await best.evaluate((element) => {
      const changes: string[] = [];
      element.setAttribute('data-changes', '[]');
      new MutationObserver(() => {
        changes.push(element.textContent ?? '');
        element.setAttribute('data-changes', JSON.stringify(changes));
      }).observe(element, { childList: true, characterData: true, subtree: true });
    });
    const completed = {
      version: SNAPSHOT_VERSION,
      boardCode: EXAMPLE_CODE,
      matched: EXAMPLE_PAIRS.flat(),
      selection: { kind: SelectionKind.closed },
      moves: imported,
      elapsedMs: 0,
      started: true,
    };
    await page.locator('summary').click();
    await page
      .getByLabel(ReproductionControl.snapshot, { exact: true })
      .fill(JSON.stringify(completed));
    await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
    await expect(page.locator('.card.matched')).toHaveCount(PERFECT * 2);
    const changes: unknown = JSON.parse((await best.getAttribute('data-changes')) ?? '[]');
    expect(changes, 'C12 import leaves the shown best alone').toEqual([]);
    expect(await savedBest(page), 'C12 import leaves the saved best alone').toBe(before);
  });

import { useRef } from 'react';
